module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    typedef enum logic [3:0] {
        S_A        = 4'd0,
        S_F        = 4'd1,
        S_X_MON    = 4'd2,
        S_Y_CHECK0 = 4'd3,
        S_Y_CHECK1 = 4'd4,
        S_G_PERM   = 4'd5,
        S_G_ZERO   = 4'd6
    } state_t;

    state_t state, next_state;
    logic [2:0] x_reg;

    // Sequential logic
    always_ff @(posedge clk) begin
        if (!resetn) begin
            state <= S_A;
            x_reg <= 3'b000;
        end else begin
            state <= next_state;
            if (state == S_X_MON) begin
                x_reg <= {x_reg[1:0], x};
            end else if (state == S_A || state == S_F) begin
                x_reg <= 3'b000;
            end
        end
    end

    // Combinational next-state logic
    always_comb begin
        next_state = state;
        f = 1'b0;
        g = 1'b0;

        case (state)
            S_A: begin
                f = 1'b0;
                g = 1'b0;
                if (resetn) begin
                    next_state = S_F;
                end
            end

            S_F: begin
                f = 1'b1;
                g = 1'b0;
                next_state = S_X_MON;
            end

            S_X_MON: begin
                f = 1'b0;
                g = 1'b0;
                if ({x_reg[1:0], x} == 3'b101) begin
                    next_state = S_Y_CHECK0;
                end else begin
                    next_state = S_X_MON;
                end
            end

            S_Y_CHECK0: begin
                f = 1'b0;
                g = 1'b1;
                if (y) begin
                    next_state = S_G_PERM;
                end else begin
                    next_state = S_Y_CHECK1;
                end
            end

            S_Y_CHECK1: begin
                f = 1'b0;
                g = 1'b1;
                if (y) begin
                    next_state = S_G_PERM;
                end else begin
                    next_state = S_G_ZERO;
                end
            end

            S_G_PERM: begin
                f = 1'b0;
                g = 1'b1;
                next_state = S_G_PERM;
            end

            S_G_ZERO: begin
                f = 1'b0;
                g = 1'b0;
                next_state = S_G_ZERO;
            end

            default: begin
                next_state = S_A;
            end
        endcase
    end

endmodule

