module tb_TopModule;
    logic clk;
    logic resetn;
    logic x;
    logic y;
    logic f;
    logic g;

    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .x(x),
        .y(y),
        .f(f),
        .g(g)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        resetn = 0;
        x = 0;
        y = 0;

        // Apply reset
        #12;
        resetn = 1; // de-assert reset

        // Next clock edge f should be 1 for 1 cycle
        @(posedge clk);
        #1;
        $display("Time %0t: f=%b (expect 1)", $time, f);
        if (f !== 1'b1) $display("FAIL f");

        // Now monitor x: send 1, 0, 1
        @(posedge clk);
        #1;
        $display("Time %0t: f=%b (expect 0)", $time, f);
        if (f !== 1'b0) $display("FAIL f after 1 cycle");

        // x = 1
        x = 1;
        @(posedge clk);
        #1;
        // x = 0
        x = 0;
        @(posedge clk);
        #1;
        // x = 1
        x = 1;
        @(posedge clk);
        #1;
        // Now next cycle g should be 1
        $display("Time %0t: g=%b (expect 1)", $time, g);
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g not 1 after 1,0,1");
            $finish;
        end

        // Test y within 2 cycles (let's set y = 1 on cycle 1 of checking)
        y = 1;
        @(posedge clk);
        #1;
        $display("Time %0t: g=%b (expect 1 permanent)", $time, g);
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g dropped when y=1");
            $finish;
        end

        // Wait a few cycles, g should stay 1
        @(posedge clk);
        @(posedge clk);
        #1;
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g not permanent");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic resetn;
    logic x;
    logic y;
    logic f;
    logic g;

    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .x(x),
        .y(y),
        .f(f),
        .g(g)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        resetn = 0;
        x = 0;
        y = 0;

        // Test case 1: Reset active
        #12;
        if (f !== 0 || g !== 0) begin
            $display("SELFTEST FAIL: outputs not 0 during reset");
            $finish;
        end

        // De-assert reset
        resetn = 1;

        // Next clock edge f should be 1 for 1 cycle
        @(posedge clk);
        #1;
        if (f !== 1'b1) begin
            $display("SELFTEST FAIL: f not 1 after reset de-assertion");
            $finish;
        end

        @(posedge clk);
        #1;
        if (f !== 1'b0) begin
            $display("SELFTEST FAIL: f did not return to 0");
            $finish;
        end

        // Send x = 1, 0, 1
        x = 1; @(posedge clk); #1;
        x = 0; @(posedge clk); #1;
        x = 1; @(posedge clk); #1;

        // g should now be 1
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g not 1 after 1,0,1");
            $finish;
        end

        // Test sub-case A: y does NOT become 1 within 2 cycles -> g goes to 0 permanently
        y = 0;
        @(posedge clk); // Cycle 1 of y check (g=1)
        #1;
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g dropped too early");
            $finish;
        end

        y = 0;
        @(posedge clk); // Cycle 2 of y check (g=1)
        #1;
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g dropped too early on cycle 2");
            $finish;
        end

        @(posedge clk); // Next cycle after 2 cycles without y=1 -> g should be 0
        #1;
        if (g !== 1'b0) begin
            $display("SELFTEST FAIL: g did not drop to 0 after y timeout");
            $finish;
        end

        // Verify g stays 0 permanently
        @(posedge clk); #1;
        if (g !== 1'b0) begin
            $display("SELFTEST FAIL: g not permanent zero");
            $finish;
        end

        // Now test reset and y becoming 1 on second cycle
        resetn = 0;
        @(posedge clk);
        #1;
        resetn = 1;
        @(posedge clk); // f=1
        @(posedge clk); // start x monitor

        x = 1; @(posedge clk); #1;
        x = 0; @(posedge clk); #1;
        x = 1; @(posedge clk); #1; // g=1

        // y check cycle 1: y=0
        y = 0; @(posedge clk); #1;
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g dropped on cycle 1");
            $finish;
        end

        // y check cycle 2: y=1
        y = 1; @(posedge clk); #1;
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g dropped when y=1 on cycle 2");
            $finish;
        end

        // Verify g stays 1 permanently
        @(posedge clk); #1;
        if (g !== 1'b1) begin
            $display("SELFTEST FAIL: g not permanent one");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

